__NUXT_JSONP__("/inclusion/eventos/las_mujeres_en_el_sector_agricola_enfrentan_una_sobrecarga_de_trabajo_de_cuidados", (function(a,b,c,d,e){return {data:[{post:{slug:"las_mujeres_en_el_sector_agricola_enfrentan_una_sobrecarga_de_trabajo_de_cuidados",title:"Las mujeres en el sector agrícola enfrentan una sobrecarga de trabajo de cuidados",date:"2025-03-19T23:26:41.860Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc0432d79-1c4e-4cd7-b5b0-85234c5ebea9\u002F-\u002Fcrop\u002F1441x918\u002F9,107\u002F-\u002Fpreview\u002F","img-alt":"Mónica Corona, Ethos",autor:"Ethos",category:"inclusion",extracto:"En el Seminario Mujeres en el Sector Agrícola Mexicano, Mónica Corona, directora de Inclusión y Desarrollo Sostenible de Ethos, expresó que la sobrecarga de cuidados que viven las mujeres trabajadoras del sector agrícola impacta negativamente en sus condiciones laborales y de vida. ",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La división desigual de las responsabilidades de cuidado representa una sobrecarga para las mujeres trabajadoras en el sector agrícola e impacta negativamente en sus condiciones laborales y de vida, dijo Mónica Corona, directora de Inclusión y Desarrollo Sostenible de Ethos, en un seminario organizado por la "},{type:b,tag:"a",props:{href:"https:\u002F\u002Fahifores.com\u002F",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:"Alianza Hortofrutícola Internacional para el Fomento de la Responsabilidad Social (Ahifores)"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al presentar la ponencia “Mujeres en el sector agrícola: aspectos de la desigualdad por razones de género”, compartió que las trabajadoras agrícolas, en su mayoría, están a cargo del cuidado de sus hijas e hijos y, algunas veces, también de sus madres o padres, lo cual genera una doble o triple jornada de trabajo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“De acuerdo con el Coneval, la mitad de las mujeres que trabajan como jornaleras agrícolas tiene hijos menores de edad, y enfrentan la falta de guarderías o de centros comunitarios para el cuidado de sus hijas e hijos; la falta de centros de atención para personas mayores, o la falta de servicios médicos en zonas agrícolas, lo cual irremediablemente agrava la carga de cuidados para ellas” dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Enfatizó que esa situación difícilmente es compatible con las exigencias de empleos formales, los cuales suelen exigir horarios rígidos y disponibilidad continua, y hace que muchas mujeres se empleen en la informalidad, lo cual conlleva ingresos inestables, falta de acceso a derechos laborales y protección social, y perpetúa su vulnerabilidad económica."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para aliviar la sobrecarga de trabajo de cuidados que enfrentan las mujeres trabajadoras agrícolas y promover la igualdad de género en este sector, Mónica Corona expresó que se requiere la colaboración activa de las empresas con políticas internas que favorezcan la redistribución del trabajo de cuidados y promuevan la equidad salarial."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Particularmente recomendó la implementación de sistemas integrales de cuidados con enfoque interseccional, fomentar la igualdad salarial, impulsar la participación activa de las mujeres en la toma de decisiones agrícolas y promover que las trabajadoras agrícolas, especialmente las que laboran en la informalidad accedan a mecanismos de protección social que incluyan prestaciones como licencias de maternidad, atención médica y apoyos en situaciones de emergencia familiar."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Flas_mujeres_en_el_sector_agricola_enfrentan_una_sobrecarga_de_trabajo_de_cuidados",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-04-23T06:21:15.374Z")));